// 尖角题七个动作在赛车游戏 Car 构造器里的落点示例
public class Car {
    private static int count = 0;          // ① 计数器：统计造了多少辆
    private int enginePower;               // ③ 重要实例变量
    private int startLap;                  // ② 出生瞬间的运行时状态
    private Object owner;                  // ④ 创建者（由参数传入并保存）
    private Engine engine;                 // ⑥ HAS-A 从属对象
    // ⑤ 把新对象登记进共享名单：名单由外部传入，构造器负责 add
    public Car(int power, int lap, Object owner, java.util.ArrayList<Car> roster) {
        count++;                           // ①
        startLap = lap;                    // ②
        enginePower = power;               // ③
        this.owner = owner;                // ④
        engine = new Engine();             // ⑥
        roster.add(this);                  // ⑤
        if (power < 0) throw new IllegalArgumentException("马力不能为负"); // ⑦ 自己的想法：合法性检查
    }
}

